mapper.select:
SELECT id FROM diagnosis_event_outbox
WHERE status = 'PENDING' AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, id LIMIT #{limit}

SELECT id FROM diagnosis_event_outbox
WHERE status = 'IN_FLIGHT' AND lease_expires_at <= #{now}
ORDER BY lease_expires_at, id LIMIT #{limit}

mapper.update:
UPDATE diagnosis_event_outbox
SET status = 'IN_FLIGHT', attempt_count = attempt_count + 1,
    lease_owner = #{leaseOwner}, lease_token = #{leaseToken}, lease_expires_at = #{leaseExpiresAt},
    updated_at = #{now}
WHERE id = #{id} AND status = 'PENDING' AND next_attempt_at <= #{now}

UPDATE diagnosis_event_outbox
SET status = 'PENDING', next_attempt_at = #{now}, lease_owner = NULL, lease_token = NULL,
    lease_expires_at = NULL, last_error_code = 'LEASE_EXPIRED', updated_at = #{now}
WHERE status = 'IN_FLIGHT' AND lease_expires_at <= #{now}

UPDATE diagnosis_event_outbox
SET status = 'PENDING', next_attempt_at = #{now}, lease_owner = NULL, lease_token = NULL,
    lease_expires_at = NULL, last_error_code = 'LEASE_EXPIRED', updated_at = #{now}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND lease_expires_at <= #{now}

UPDATE diagnosis_event_outbox
SET status = 'DELIVERED', delivered_at = #{now}, lease_owner = NULL, lease_token = NULL,
    lease_expires_at = NULL, last_error_code = NULL, updated_at = #{now}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND lease_token = #{leaseToken} AND lease_expires_at > #{now}

UPDATE diagnosis_event_outbox
SET status = 'PENDING', next_attempt_at = #{nextAttemptAt}, lease_owner = NULL, lease_token = NULL,
    lease_expires_at = NULL, last_error_code = #{errorCode}, updated_at = #{now}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND lease_token = #{leaseToken} AND lease_expires_at > #{now}

UPDATE diagnosis_event_outbox
SET status = 'DEAD', lease_owner = NULL, lease_token = NULL, lease_expires_at = NULL,
    last_error_code = #{errorCode}, updated_at = #{now}
WHERE id = #{id} AND status = 'IN_FLIGHT' AND lease_token = #{leaseToken} AND lease_expires_at > #{now}
